import numpy as np, torch, model
torch.manual_seed(0); np.random.seed(0)
net=model.load(); w=torch.tensor(np.load('contrast_c0_blocks.1_k10.npy')); b=-6.2562
N=4096; xi=torch.randn(N,2); c=torch.rand(N)
st={'k':0,'gate':None,'off':None,'K':(0,11),'thr':0.0}
def h1(m,i,o):
    s=o@w+b; st['s']=s
    st['gate']=(s>st['thr']).float()*float(st['K'][0]<=st['k']<st['K'][1])
def ho(m,i,o):
    if st['off'] is None: return o
    return o+st['gate'][:,None]*st['off'][None,:]
net.blocks[1].register_forward_hook(h1); net.out.register_forward_hook(ho)
def dec(off,K=(0,11),thr=0.0):
    st['off']=None if off is None else torch.tensor(off,dtype=torch.float32); st['K']=K; st['thr']=thr
    x=xi.clone(); S=[]
    with torch.no_grad():
        for k in range(20):
            st['k']=k; t=torch.full((N,),1-k/20)
            v,_=net.velocity(x,t,c,(),count=False); S.append(st['s'].clone())
            x=x-v/20
    return x.numpy(),torch.stack(S).numpy()
A0,S0=dec(None)
tgt=S0[10]>0; print('target share',tgt.mean(), 'final-step agree', ((S0[19]>0)==tgt).mean())
C=c.numpy()
ang=np.degrees(np.arctan2(A0[:,1],A0[:,0]))
for lo in np.arange(0,1,0.2):
    m=(C>=lo)&(C<lo+0.2)
    print(round(lo,1), np.histogram(ang[m&tgt],bins=np.arange(-180,181,30))[0], np.histogram(ang[m&~tgt],bins=np.arange(-180,181,30))[0])
np.savez('sim0.npz',xi=xi.numpy(),c=C,a0=A0,tgt=tgt,S0=S0)
# classifier for target on outcomes: kNN in (a, 3*c)
F0=np.c_[A0,3*C]
def is_tgt(A):
    F=np.c_[A,3*C]; d=((F[:,None,:]-F0[None,:,:])**2).sum(-1); nn=np.argsort(d,1)[:,:7]
    return tgt[nn].mean(1)>0.5, np.sqrt(np.sort(d,1)[:,1])
_,nd0=is_tgt(A0); off_thr=np.quantile(nd0,0.98)
def evals(A):
    tt,nd=is_tgt(A); mv=np.linalg.norm(A-A0,axis=1)
    return dict(tgt_after=round(tt.mean(),3), tgt_fall=round(1-tt.mean()/tgt.mean(),3), drift_keep=round((mv[~tgt]>0.3).mean(),3), offdist=round((nd>off_thr).mean()-0.02,3))
for deg in range(0,360,45):
    for mag in [2,4]:
        u=np.array([np.cos(np.radians(deg)),np.sin(np.radians(deg))])*mag
        A,_=dec(u); print(deg,mag,evals(A))

