import numpy as np, torch, model
net=model.load(); p=np.load('track.npy')
def lab(a,c):
    an=np.degrees(np.arctan2(a[:,1],a[:,0]))%360; d=((an-np.polyval(p,c)+180)%360)-180
    return (np.abs(d)<22.5)&(np.linalg.norm(a,axis=1)>1.5)
torch.manual_seed(7); N=6000; xi=torch.randn(N,2); c=torch.rand(N); cc=c.numpy()
a0=model.decode(net,xi,c).numpy(); bad0=lab(a0,cc); r0=np.linalg.norm(a0,axis=1)
cg=np.linspace(0,1,50)
def ufit(sign):
    phi=np.radians(np.polyval(p,cg)+sign*90); U=np.c_[np.cos(phi),np.sin(phi)]
    M=np.c_[cg,np.ones_like(cg)]; coef,_,_,_=np.linalg.lstsq(M,U,rcond=None); return coef  # rows: u1,u0
def sim(sign,g,det,LO,HI,thr=0.):
    P=np.load(det); w=torch.tensor(P[:128]); b=float(P[128]); co=torch.tensor(ufit(sign)).float()
    x=xi.clone()
    for k in range(20):
        t=torch.full((N,),1-k/20); v,A=net.velocity(x,t,c,('blocks.1',),count=False)
        f=((A['blocks.1']@w+b)>thr)&(LO<=k<HI)
        u=c[:,None]*co[0]+co[1]
        v=v-g*f[:,None].float()*u
        x=x-v/20
    return x.numpy()
